CREATE TABLE public.directory_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),dedupe_key uuid NOT NULL UNIQUE,event text NOT NULL CHECK(event IN ('search','zero_result_search','result_click','business_view','offering_view','call_click','whatsapp_click','enquiry_saved','assignment_created','notification_outcome','first_vendor_response','quote_sent','reported_won','reported_lost')),business_id uuid REFERENCES public.businesses(id),offering_id uuid REFERENCES public.business_offerings(id),city text NOT NULL DEFAULT '',category text NOT NULL DEFAULT '',term text NOT NULL DEFAULT '',source text NOT NULL DEFAULT '',medium text NOT NULL DEFAULT '',campaign text NOT NULL DEFAULT '',outcome text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.directory_events TO authenticated; GRANT ALL ON public.directory_events TO service_role;
ALTER TABLE public.directory_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY event_read ON public.directory_events FOR SELECT TO authenticated USING(public.ops_permission('operations.read',business_id) OR EXISTS(SELECT 1 FROM public.businesses WHERE id=business_id AND owner_id=auth.uid()));
CREATE INDEX directory_events_aggregate ON public.directory_events(created_at,event,business_id);
CREATE OR REPLACE FUNCTION public.record_directory_event(payload jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid:=nullif(payload->>'business_id','')::uuid; oid uuid:=nullif(payload->>'offering_id','')::uuid; b public.businesses; e text:=payload->>'event'; BEGIN IF e NOT IN ('search','zero_result_search','result_click','business_view','offering_view','call_click','whatsapp_click') THEN RAISE EXCEPTION 'Unsupported public event'; END IF;
IF bid IS NOT NULL THEN SELECT * INTO b FROM public.businesses WHERE id=bid AND status='approved'; IF b.id IS NULL THEN RETURN; END IF; END IF;
IF oid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.business_offerings WHERE id=oid AND business_id=bid AND published) THEN RETURN; END IF;
IF length(coalesce(payload->>'term',''))>100 OR coalesce(payload->>'term','') ~ '@|[0-9]{6}' OR length(coalesce(payload->>'city',''))>100 OR length(coalesce(payload->>'category',''))>100 THEN RETURN; END IF;
INSERT INTO public.directory_events(dedupe_key,event,business_id,offering_id,city,category,term,source,medium,campaign) VALUES((payload->>'dedupe_key')::uuid,e,bid,oid,coalesce(b.city,payload->>'city',''),coalesce(b.category,payload->>'category',''),coalesce(payload->>'term',''),CASE WHEN coalesce(payload->>'source','') ~ '^[a-zA-Z0-9 _.-]{0,80}$' THEN payload->>'source' ELSE '' END,CASE WHEN coalesce(payload->>'medium','') ~ '^[a-zA-Z0-9 _.-]{0,80}$' THEN payload->>'medium' ELSE '' END,CASE WHEN coalesce(payload->>'campaign','') ~ '^[a-zA-Z0-9 _.-]{0,80}$' THEN payload->>'campaign' ELSE '' END) ON CONFLICT(dedupe_key) DO NOTHING; END; $$;
REVOKE ALL ON FUNCTION public.record_directory_event(jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.record_directory_event(jsonb) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.capture_lead_operational_events() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c text; cat text; BEGIN SELECT city,category INTO c,cat FROM public.businesses WHERE id=NEW.business_id;
IF TG_OP='INSERT' THEN INSERT INTO public.directory_events(dedupe_key,event,business_id,city,category) VALUES(gen_random_uuid(),'enquiry_saved',NEW.business_id,c,cat); IF NEW.requirement_id IS NOT NULL OR NEW.assignee IS NOT NULL THEN INSERT INTO public.directory_events(dedupe_key,event,business_id,city,category) VALUES(gen_random_uuid(),'assignment_created',NEW.business_id,c,cat); END IF;
ELSE IF OLD.assignee IS DISTINCT FROM NEW.assignee AND NEW.assignee IS NOT NULL THEN INSERT INTO public.directory_events(dedupe_key,event,business_id,city,category) VALUES(gen_random_uuid(),'assignment_created',NEW.business_id,c,cat); END IF;
IF OLD.first_response_at IS NULL AND NEW.first_response_at IS NOT NULL THEN INSERT INTO public.directory_events(dedupe_key,event,business_id,city,category) VALUES(gen_random_uuid(),'first_vendor_response',NEW.business_id,c,cat); END IF;
IF OLD.quotation_sent_at IS DISTINCT FROM NEW.quotation_sent_at AND NEW.quotation_sent_at IS NOT NULL THEN INSERT INTO public.directory_events(dedupe_key,event,business_id,city,category) VALUES(gen_random_uuid(),'quote_sent',NEW.business_id,c,cat); END IF;
IF OLD.status IS DISTINCT FROM NEW.status AND NEW.status IN ('won','lost') THEN INSERT INTO public.directory_events(dedupe_key,event,business_id,city,category) VALUES(gen_random_uuid(),'reported_'||NEW.status,NEW.business_id,c,cat); END IF; END IF; RETURN NEW; END; $$;
CREATE TRIGGER lead_operational_events AFTER INSERT OR UPDATE ON public.leads FOR EACH ROW EXECUTE FUNCTION public.capture_lead_operational_events();
CREATE OR REPLACE FUNCTION public.capture_notification_outcome() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF OLD.status IS DISTINCT FROM NEW.status THEN INSERT INTO public.directory_events(dedupe_key,event,business_id,outcome) VALUES(gen_random_uuid(),'notification_outcome',NEW.business_id,NEW.status); END IF; RETURN NEW; END; $$;
CREATE TRIGGER notification_outcomes AFTER UPDATE ON public.in_app_notifications FOR EACH ROW EXECUTE FUNCTION public.capture_notification_outcome();
CREATE OR REPLACE FUNCTION public.operations_summary(filters jsonb,owner_only boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; from_date timestamptz:=coalesce(nullif(filters->>'from','')::timestamptz,now()-interval '30 days'); to_date timestamptz:=coalesce(nullif(filters->>'to','')::timestamptz,now()); city_filter text:=coalesce(filters->>'city',''); category_filter text:=coalesce(filters->>'category',''); aid uuid:=nullif(filters->>'assignee','')::uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; IF NOT owner_only AND NOT public.is_staff() THEN RAISE EXCEPTION 'Staff permission required'; END IF;
WITH bs AS (SELECT b.* FROM public.businesses b WHERE (CASE WHEN owner_only THEN b.owner_id=auth.uid() ELSE public.ops_permission('operations.read',b.id) END) AND (city_filter='' OR b.city=city_filter) AND (category_filter='' OR b.category=category_filter)), ls AS (SELECT l.* FROM public.leads l JOIN bs ON bs.id=l.business_id WHERE l.created_at BETWEEN from_date AND to_date AND (aid IS NULL OR l.assignee=aid)), ev AS (SELECT e.* FROM public.directory_events e WHERE e.created_at BETWEEN from_date AND to_date AND (e.business_id IN (SELECT id FROM bs) OR NOT owner_only AND e.business_id IS NULL AND public.ops_permission('operations.read')) AND (city_filter='' OR e.city=city_filter) AND (category_filter='' OR e.category=category_filter) AND aid IS NULL), ts AS (SELECT t.* FROM public.support_tickets t WHERE (CASE WHEN owner_only THEN t.requester_id=auth.uid() ELSE public.ops_permission('support.manage',t.business_id) END) AND t.created_at BETWEEN from_date AND to_date AND (city_filter='' AND category_filter='' OR t.business_id IN (SELECT id FROM bs)) AND (aid IS NULL OR t.assignee=aid)), req AS (SELECT r.* FROM public.buy_requirements r WHERE (owner_only AND r.requester_id=auth.uid() OR NOT owner_only AND public.ops_permission('leads.manage')) AND r.created_at BETWEEN from_date AND to_date AND (city_filter='' OR r.city=city_filter) AND (category_filter='' OR r.category=category_filter) AND aid IS NULL)
SELECT jsonb_build_object('queues',jsonb_build_array(jsonb_build_object('key','requirements','label','New requirements','count',(SELECT count(*) FROM req WHERE status='new')),jsonb_build_object('key','unassigned','label','Unassigned leads','count',(SELECT count(*) FROM ls WHERE assignee IS NULL AND status='new')),jsonb_build_object('key','overdue_leads','label','Overdue vendor responses','count',(SELECT count(*) FROM ls WHERE response_due_at<now() AND first_response_at IS NULL AND status NOT IN ('won','lost'))),jsonb_build_object('key','approvals','label','Pending listing approvals','count',(SELECT count(*) FROM bs WHERE status='pending' AND created_at BETWEEN from_date AND to_date)),jsonb_build_object('key','claims','label','Claims awaiting evidence/review','count',(SELECT count(*) FROM public.business_claims c WHERE c.business_id IN (SELECT id FROM bs) AND c.status IN ('submitted','evidence_requested','under_review') AND c.created_at BETWEEN from_date AND to_date)),jsonb_build_object('key','tickets','label','Open tickets','count',(SELECT count(*) FROM ts WHERE status NOT IN ('resolved','closed'))),jsonb_build_object('key','overdue_tickets','label','Overdue tickets','count',(SELECT count(*) FROM ts WHERE response_due_at<now() AND status NOT IN ('resolved','closed'))),jsonb_build_object('key','notifications','label','Failed in-app notifications','count',(SELECT count(*) FROM public.in_app_notifications n WHERE n.status='failed' AND n.created_at BETWEEN from_date AND to_date AND (owner_only AND n.recipient_id=auth.uid() OR NOT owner_only AND public.ops_permission('operations.read',n.business_id)) AND (city_filter='' AND category_filter='' OR n.business_id IN (SELECT id FROM bs)) AND aid IS NULL)),jsonb_build_object('key','quality','label','Data-quality issues','count',(SELECT count(*) FROM public.directory_quality_issues q WHERE NOT owner_only AND public.has_permission('staff.manage') AND q.business_id IN (SELECT id FROM bs) AND q.status NOT IN ('resolved','dismissed') AND q.created_at BETWEEN from_date AND to_date AND (aid IS NULL OR q.assignee=aid))),jsonb_build_object('key','zero_search','label','Zero-result searches','count',(SELECT count(*) FROM ev WHERE event='zero_result_search'))),'metrics',coalesce((SELECT jsonb_object_agg(event,n) FROM (SELECT event,count(*) n FROM ev GROUP BY event) x),'{}'::jsonb),'businesses',(SELECT count(*) FROM bs),'saved_enquiries',(SELECT count(*) FROM ls),'quotations',(SELECT count(*) FROM ls WHERE quotation_sent_at IS NOT NULL),'reported_won',(SELECT count(*) FROM ls WHERE status='won'),'reported_lost',(SELECT count(*) FROM ls WHERE status='lost'),'response_minutes',(SELECT round(avg(extract(epoch FROM first_response_at-created_at)/60)::numeric,1) FROM ls WHERE first_response_at IS NOT NULL),'zero_terms',coalesce((SELECT jsonb_agg(x) FROM (SELECT term,city,category,count(*) count FROM ev WHERE event='zero_result_search' GROUP BY term,city,category ORDER BY count(*) DESC LIMIT 30) x),'[]'::jsonb)) INTO result; RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.operations_summary(jsonb,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.operations_summary(jsonb,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.operations_records(filters jsonb,queue_key text,page_number integer DEFAULT 1) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rows_json jsonb; from_date timestamptz:=coalesce(nullif(filters->>'from','')::timestamptz,now()-interval '30 days'); to_date timestamptz:=coalesce(nullif(filters->>'to','')::timestamptz,now()); cf text:=coalesce(filters->>'city',''); catf text:=coalesce(filters->>'category',''); aid uuid:=nullif(filters->>'assignee','')::uuid; BEGIN IF NOT public.is_staff() THEN RAISE EXCEPTION 'Staff permission required'; END IF;
WITH bs AS (SELECT * FROM public.businesses b WHERE public.ops_permission('operations.read',b.id) AND (cf='' OR city=cf) AND (catf='' OR category=catf)), records AS (
SELECT r.id,r.topic title,r.status,r.created_at,'Requirement' kind,r.city,r.category FROM public.buy_requirements r WHERE queue_key='requirements' AND public.ops_permission('leads.manage') AND r.status='new' AND (cf='' OR r.city=cf) AND (catf='' OR r.category=catf) AND aid IS NULL
UNION ALL SELECT l.id,bs.name,l.status,l.created_at,'Lead',bs.city,bs.category FROM public.leads l JOIN bs ON bs.id=l.business_id WHERE (queue_key='unassigned' AND l.assignee IS NULL AND l.status='new' OR queue_key='overdue_leads' AND l.response_due_at<now() AND l.first_response_at IS NULL AND l.status NOT IN ('won','lost')) AND (aid IS NULL OR l.assignee=aid)
UNION ALL SELECT b.id,b.name,b.status,b.created_at,'Listing',b.city,b.category FROM bs b WHERE queue_key='approvals' AND b.status='pending'
UNION ALL SELECT c.id,bs.name,c.status,c.created_at,'Claim',bs.city,bs.category FROM public.business_claims c JOIN bs ON bs.id=c.business_id WHERE queue_key='claims' AND c.status IN ('submitted','evidence_requested','under_review')
UNION ALL SELECT t.id,t.reference||' · '||t.topic,t.status,t.created_at,'Ticket',coalesce(b.city,''),coalesce(b.category,'') FROM public.support_tickets t LEFT JOIN bs b ON b.id=t.business_id WHERE public.ops_permission('support.manage',t.business_id) AND (cf='' AND catf='' OR b.id IS NOT NULL) AND (aid IS NULL OR t.assignee=aid) AND t.status NOT IN ('resolved','closed') AND (queue_key='tickets' OR queue_key='overdue_tickets' AND t.response_due_at<now())
UNION ALL SELECT n.id,n.title,n.status,n.created_at,'In-app notification',coalesce(b.city,''),coalesce(b.category,'') FROM public.in_app_notifications n LEFT JOIN bs b ON b.id=n.business_id WHERE queue_key='notifications' AND public.ops_permission('operations.read',n.business_id) AND n.status='failed' AND (cf='' AND catf='' OR b.id IS NOT NULL) AND aid IS NULL
UNION ALL SELECT q.id,q.summary,q.status,q.created_at,'Quality issue',bs.city,bs.category FROM public.directory_quality_issues q JOIN bs ON bs.id=q.business_id WHERE queue_key='quality' AND public.has_permission('staff.manage') AND q.status NOT IN ('resolved','dismissed') AND (aid IS NULL OR q.assignee=aid)
UNION ALL SELECT e.id,e.term,e.event,e.created_at,'Search',e.city,e.category FROM public.directory_events e WHERE queue_key='zero_search' AND e.event='zero_result_search' AND public.ops_permission('operations.read') AND (cf='' OR e.city=cf) AND (catf='' OR e.category=catf) AND aid IS NULL)
SELECT coalesce(jsonb_agg(x),'[]'::jsonb) INTO rows_json FROM (SELECT * FROM records WHERE created_at BETWEEN from_date AND to_date ORDER BY created_at DESC LIMIT 30 OFFSET (greatest(1,page_number)-1)*30) x; RETURN rows_json; END; $$;
REVOKE ALL ON FUNCTION public.operations_records(jsonb,text,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.operations_records(jsonb,text,integer) TO authenticated;